/**
 * Shared bits for the Blackjack, Batteries, Wire Placement, Laundry and Battleship tabs
 * (ported from bomb_boomed): their look (.mk-*), taking pictures in (click, drop, paste — several
 * at once), and copying an answer. Reading and solving come from bomb-logic.js
 * (window.BombLogic.<module>), generated by bomb_boomed's scripts/build-conso-logic.mjs.
 */
(function () {
  'use strict';

  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const cap = (s) => (s ? s[0].toUpperCase() + s.slice(1) : '');

  function injectBase() {
    if ($('moduleKitStyles')) return;
    const style = document.createElement('style');
    style.id = 'moduleKitStyles';
    style.textContent = `
    .mk-shell { max-width: 1100px; margin: 0 auto 30px; background: #0d0f22; border: 1.5px solid #202448; border-radius: 18px; padding: 24px; color: #e2e8f0; font-family: 'Inter', system-ui, sans-serif; box-shadow: 0 12px 40px rgba(0,0,0,0.6); }
    .mk-head { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 12px; margin-bottom: 20px; padding-bottom: 16px; border-bottom: 1px solid #1c2042; }
    .mk-title { font-family: 'Outfit', sans-serif; font-size: 24px; font-weight: 800; color: #ffd875; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    .mk-pill { font-family: 'Inter', system-ui, sans-serif; font-size: 13px; font-weight: 600; color: #94a3b8; background: #181b36; padding: 3px 10px; border-radius: 99px; border: 1px solid #282d58; }
    .mk-actions { display: flex; gap: 8px; flex-wrap: wrap; }
    .mk-layout { display: grid; grid-template-columns: minmax(0, 380px) minmax(0, 1fr); gap: 24px; align-items: start; }
    .mk-layout > * { min-width: 0; }
    @media (max-width: 860px) { .mk-layout { grid-template-columns: minmax(0, 1fr); } }
    @media (max-width: 600px) { .mk-shell { padding: 14px; border-radius: 14px; } .mk-title { font-size: 20px; } .mk-answer { font-size: 24px; } }
    .mk-card { background: #070814; border: 1px solid #1c2042; border-radius: 14px; padding: 16px; margin-bottom: 16px; }
    .mk-card-title { font-family: 'Outfit', sans-serif; font-size: 14px; font-weight: 700; color: #ffd875; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.8px; }
    .mk-dropzone { border: 2px dashed #343864; border-radius: 12px; padding: 20px 14px; text-align: center; cursor: pointer; background: rgba(255,255,255,0.015); transition: all 0.2s; margin-bottom: 12px; }
    .mk-dropzone:hover, .mk-dropzone.dragover { border-color: #ffd875; background: rgba(255,216,117,0.06); }
    .mk-drop-icon { font-size: 26px; margin-bottom: 6px; }
    .mk-drop-title { font-weight: 700; font-size: 14px; color: #fff; margin-bottom: 4px; }
    .mk-drop-sub { font-size: 12px; color: #94a3b8; line-height: 1.5; }
    .mk-dropzone kbd { background: #1e2246; padding: 2px 6px; border-radius: 4px; color: #ffd875; font-family: inherit; }
    .mk-btn { background: #181b36; border: 1px solid #2d3366; color: #cbd5e1; padding: 7px 12px; border-radius: 8px; font-size: 13px; font-weight: 700; cursor: pointer; transition: all 0.15s; font-family: inherit; }
    .mk-btn:hover:not(:disabled) { border-color: #ffd875; color: #ffd875; }
    .mk-btn:disabled { opacity: 0.45; cursor: default; }
    .mk-btn.gold { background: #2a2410; border-color: #f5c542; color: #ffd875; }
    .mk-btn.small { padding: 4px 9px; font-size: 12px; }
    .mk-status { font-size: 13px; line-height: 1.5; padding: 8px 11px; border-radius: 9px; background: #12152e; border: 1px solid #232a58; color: #cbd5e1; margin-bottom: 12px; word-break: break-word; }
    .mk-status.ok { border-color: rgba(74,222,128,0.45); color: #a7f3c0; }
    .mk-status.bad { border-color: rgba(255,95,87,0.45); color: #ff9b94; background: rgba(255,95,87,0.06); }
    .mk-banner { background: linear-gradient(135deg, rgba(255,216,117,0.10) 0%, rgba(245,197,66,0.04) 100%); border: 2px solid #f5c542; border-radius: 14px; padding: 16px 20px; margin-bottom: 16px; box-shadow: 0 0 25px rgba(245,197,66,0.12); }
    .mk-banner-row { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; }
    .mk-banner-row > div:first-child { min-width: 0; flex: 1; }
    .mk-banner-lbl { font-size: 12px; font-weight: 800; color: #ffd875; letter-spacing: 1px; text-transform: uppercase; }
    .mk-answer { font-family: 'Outfit', sans-serif; font-size: 30px; font-weight: 900; margin-top: 2px; color: #fff; line-height: 1.25; word-break: break-word; }
    .mk-answer .ph { color: #64748b; font-size: 18px; font-weight: 700; letter-spacing: 0.5px; }
    .mk-answer.lines { font-size: 19px; font-weight: 800; }
    .mk-answer.lines div + div { margin-top: 4px; }
    .mk-stats { font-size: 12px; color: #94a3b8; margin-top: 4px; }
    .mk-warn { background: rgba(255,95,87,0.08); border: 1px solid rgba(255,95,87,0.4); color: #ff9b94; border-radius: 10px; padding: 9px 12px; font-size: 13px; margin-bottom: 10px; }
    .mk-note { background: #12152e; border: 1px solid #232a58; border-radius: 10px; padding: 10px 12px; font-size: 13px; color: #cbd5e1; line-height: 1.55; margin-bottom: 12px; }
    .mk-dim { color: #8892b0; font-size: 12px; }
    .mk-label { font-size: 11px; font-weight: 800; color: #94a3b8; letter-spacing: 0.8px; text-transform: uppercase; }
    .mk-row { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
    .mk-row > .mk-label { min-width: 92px; }
    .mk-ok { color: #4ade80; font-size: 13px; font-weight: 600; }
    .mk-need { color: #94a3b8; font-size: 13px; font-style: italic; }
    .mk-thumb { max-height: 44px; max-width: 90px; border-radius: 6px; border: 1px solid #2a315e; }
    .mk-select, .mk-input, .mk-textarea { background: #0b0d1d; border: 1px solid #2a2f5c; color: #e2e8f0; border-radius: 7px; font-family: inherit; font-size: 13px; padding: 5px 7px; max-width: 100%; }
    .mk-select:focus, .mk-input:focus, .mk-textarea:focus { outline: none; border-color: #ffd875; }
    .mk-textarea { width: 100%; box-sizing: border-box; min-height: 92px; resize: vertical; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 12px; line-height: 1.5; margin: 4px 0 10px; }
    .mk-chip { display: inline-flex; align-items: center; gap: 5px; background: #161936; border: 1px solid #2d3366; border-radius: 8px; padding: 3px 7px; font-size: 12px; }
    .mk-x { background: none; border: none; color: #94a3b8; cursor: pointer; font-size: 12px; padding: 0 2px; }
    .mk-x:hover { color: #ff9b94; }
    .mk-details { background: #070814; border: 1px solid #1c2042; border-radius: 12px; padding: 10px 14px; margin-bottom: 14px; }
    .mk-details summary { color: #ffd875; font-weight: 700; font-size: 13px; cursor: pointer; outline: none; }
    .mk-details[open] summary { margin-bottom: 10px; }
    .mk-table-wrap { overflow-x: auto; max-width: 100%; }
    .mk-table { border-collapse: collapse; font-size: 12px; min-width: 100%; }
    .mk-table th, .mk-table td { border-bottom: 1px solid #1a1e3d; padding: 4px 5px; text-align: center; color: #cbd5e1; white-space: nowrap; }
    .mk-table th { color: #94a3b8; font-weight: 700; }
    .mk-table tr.on td, .mk-table tr.on th { background: rgba(255,216,117,0.07); }
    .mk-table .used { background: rgba(255,216,117,0.10); }
    `;
    document.head.appendChild(style);
  }

  function fileToImage(file) {
    return new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => {
        const img = new Image();
        img.onload = () => resolve({ img, uri: r.result, file });
        img.onerror = () => reject(new Error('Not a picture the browser can open.'));
        img.src = r.result;
      };
      r.onerror = () => reject(new Error('Could not read that file.'));
      r.readAsDataURL(file);
    });
  }

  /** The picture's pixels (ImageData). maxDim scales a huge picture down. */
  function imageData(img, maxDim = 0) {
    const w0 = img.naturalWidth || img.width, h0 = img.naturalHeight || img.height;
    const sc = maxDim ? Math.min(1, maxDim / Math.max(w0, h0)) : 1;
    const W = Math.round(w0 * sc), H = Math.round(h0 * sc);
    const c = document.createElement('canvas');
    c.width = W; c.height = H;
    const ctx = c.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(img, 0, 0, W, H);
    return ctx.getImageData(0, 0, W, H);
  }

  const isPicture = (f) => f && ((f.type || '').startsWith('image/') || /\.(png|jpe?g|webp|bmp|gif)$/i.test(f.name || ''));

  /**
   * Pictures for one tab: clicking the drop area opens the file picker; files from it, dropped
   * files (or a dropped link) and pasted pictures go to onPictures([{ img, uri, file }]).
   * A pasted link is routed to the input by dragdrop-helper.js.
   */
  function wirePictures({ sectionId, dropzoneId, inputId, onPictures }) {
    const dz = $(dropzoneId), input = $(inputId);
    const take = async (files) => {
      const items = [];
      for (const f of files.filter(isPicture)) {
        try { items.push(await fileToImage(f)); } catch (e) { /* skipped: not a picture */ }
      }
      if (items.length) onPictures(items);
    };
    if (input) {
      input.addEventListener('change', () => {
        const files = Array.from(input.files || []);
        input.value = '';
        take(files);
      });
    }
    if (dz) {
      dz.addEventListener('click', () => input && input.click());
      dz.addEventListener('dragover', (e) => { e.preventDefault(); dz.classList.add('dragover'); });
      dz.addEventListener('dragleave', () => dz.classList.remove('dragover'));
      dz.addEventListener('drop', (e) => {
        e.preventDefault();
        e.stopPropagation();
        dz.classList.remove('dragover');
        const files = Array.from(e.dataTransfer?.files || []).filter(isPicture);
        if (files.length) { take(files); return; }
        if (window.BombDragDrop) {
          window.BombDragDrop.handleDataTransfer(e.dataTransfer, (file) => { if (file) take([file]); });
        }
      });
    }
    document.addEventListener('paste', (e) => {
      if (!$(sectionId)?.classList.contains('active')) return;
      const files = [];
      for (const item of (e.clipboardData?.items || [])) {
        if (item.type.startsWith('image/')) { const f = item.getAsFile(); if (f) files.push(f); }
      }
      if (!files.length) return; // text and links: the boxes / dragdrop-helper.js take those
      e.preventDefault();
      take(files);
    });
  }

  /** Copy text; the button says whether it worked. */
  function copyText(text, btn, label) {
    if (!text) return;
    const said = label || (btn ? btn.textContent : '');
    const show = (msg) => {
      if (!btn) return;
      btn.textContent = msg;
      clearTimeout(btn._mkTimer);
      btn._mkTimer = setTimeout(() => { btn.textContent = said; }, 1500);
    };
    const fallback = () => {
      try {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed'; ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        const ok = document.execCommand('copy');
        ta.remove();
        show(ok ? '✓ Copied' : '⚠ Not copied');
      } catch (e) { show('⚠ Not copied'); }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => show('✓ Copied'), fallback);
    } else fallback();
  }

  /** The bomb's serial, shared with serial-bar.js (same storage key). */
  const SERIAL_KEY = 'ktane_bomb_serial';
  function savedSerial() { try { return localStorage.getItem(SERIAL_KEY) || ''; } catch (e) { return ''; } }

  window.ModuleKit = { $, esc, cap, injectBase, fileToImage, imageData, wirePictures, copyText, savedSerial };
})();
